def _win(front, c0, c1):
    def cut(ink, b):
        art, bb = STYLES[front](ink, b)
        out = art[:, c0:c1]
        if out.shape[1] == 0:
            out = np.zeros((art.shape[0], 1), np.uint8)
        return out, bb
    return cut

